// Second wave of catalogue entries, kept separate so objects.js stays readable.
// Same rules as objects.js: real, documented pieces only — designer, manufacturer and year
// checked against museum collections (MoMA, V&A, Cooper Hewitt, M+, NGV) and manufacturer
// sources. Where a piece has both a design date and a later production date, the design
// date is used. Photos are resolved the same way as in objects.js; entries with no verified
// free photo yet get `image: null` and render a drawn placeholder.
import { OBJECT_PHOTOS, photoUrl } from "./objectPhotos.js";

const img = (slug) => (OBJECT_PHOTOS[slug] ? photoUrl(OBJECT_PHOTOS[slug]) : null);

